from datetime import date, timedelta

def vencimentos_parcelas(data_base, parcelas):
    datas = []
    proximo = data_base

    for _ in range(parcelas):
        while proximo.weekday() >= 5:
            proximo += timedelta(days=1)
        datas.append(proximo)
        proximo += timedelta(days=30)

    return datas

